use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::Path,collections::{BTreeMap,BTreeSet},process::{Command,Stdio},io::Read};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break;}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn main(){let r=Path::new("/tmp/zopro-lower-bound-c7a");assert_eq!(read(r.join("native/result.json"))["status"],"complete");let c=r.join("context");fs::create_dir(&c).unwrap();fs::create_dir(c.join("basis")).unwrap();let mut pins=BTreeMap::new();for(mode,path)in[("accepted",Path::new("/tmp/zopro-ready-c7a/native/accepted/artifacts.json").to_path_buf()),("candidate",r.join("native/on/artifacts.json"))]{let a=read(path);assert_eq!(hash(a["binary"].as_str().unwrap()),a["binary_sha256"].as_str().unwrap());for(p,h)in a["input_pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}let name=format!("lb-{mode}");fs::copy(a["binary"].as_str().unwrap(),c.join(&name)).unwrap();pins.insert(format!("/usr/local/bin/{name}"),hash(c.join(name)));}
 for name in ["adapter","runner"]{fs::copy(r.join(name),c.join(format!("lb-{name}"))).unwrap();pins.insert(format!("/usr/local/bin/lb-{name}"),hash(r.join(name)));}fs::copy("/home/ubuntu/src/zk-tools/zopro/xtask/target/release/xtask",c.join("lb-xtask")).unwrap();pins.insert("/usr/local/bin/lb-xtask".into(),hash(c.join("lb-xtask")));
 let local=read("/tmp/zopro-grouping-lower-bound/perf-plan.json");let lock=read("/home/ubuntu/src/zk-tools/zopro/tools/zolana/zopro-keys.lock");let mut cases=Vec::new();for original in local["cases"].as_array().unwrap(){let mut case=original.clone();let image=Path::new(original["image"].as_str().unwrap());let basename=image.file_name().unwrap().to_str().unwrap();let stem=image.file_stem().unwrap().to_str().unwrap();let request=Path::new(original["request"].as_str().unwrap());let fixture=request.file_name().unwrap().to_str().unwrap();fs::copy(image,c.join("basis").join(basename)).unwrap();pins.insert(format!("/lb-basis/{basename}"),hash(image));pins.insert(format!("/fixtures/{fixture}"),hash(request));let key=&lock["keys"][format!("{stem}.key")];pins.insert(format!("/keys/{}",key["file"].as_str().unwrap()),key["sha256"].as_str().unwrap().into());pins.insert(format!("/gnark-keys/{stem}.key"),key["key_sha256"].as_str().unwrap().into());case["image"]=json!(format!("/lb-basis/{basename}"));case["request"]=json!(format!("/fixtures/{fixture}"));cases.push(case);}assert_eq!(cases.len(),9);
 let previous=read("/tmp/zopro-latest-c7a/context/current-aws.json");pins.insert("/usr/local/bin/aeglos-ablation".into(),previous["binaries"]["aeglos-default"]["sha256"].as_str().unwrap().into());for(src,name,target)in[("/tmp/zopro-gnark-verify/verify","gnark-verify","/usr/local/bin/gnark-verify"),("/home/ubuntu/src/zk-tools/zopro/tools/zolana/zopro-keys.lock","zopro-keys.lock","/manifest/zopro-keys.lock")]{fs::copy(src,c.join(name)).unwrap();pins.insert(target.into(),hash(src));}pins.insert("/usr/lib/linux-tools/6.8.0-147-generic/perf".into(),"2927eb0973fd937bdd417622531c95f1e6e19307a29c3e05a2c6198e12af6e56".into());
 let old=read("/tmp/zopro-ready-c7a/remote-results/output/measure/config.json");let mut prior:BTreeSet<String>=serde_json::from_value(old["prior_proof_sha256"].clone()).unwrap();for f in ["/tmp/zopro-ready-c7a/proof-inventory.json","/tmp/zopro-stage-costs/proof-inventory.json","/tmp/zopro-grouping-lower-bound/proof-inventory.json"]{for(p,h)in read(f).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());if p.ends_with(".proof"){prior.insert(h.as_str().unwrap().into());}}}assert_eq!(prior.len(),5340);
 let accepted=read("/tmp/zopro-grouping-module/production-source-manifest.json");assert_eq!(read(r.join("native/on-core/tests.json"))["passed_tests"].as_array().unwrap().len(),113);let manifest=json!({"scope":"Unchanged local bitmap candidate on C7a; all-nine accepted/OFF/ON/Aeglos; no stage recorder","parent_image_id":"sha256:0b79be0b9b5b9675622282a950bd87c8bb98ed092a6605c3a1cb426f6848e66b","container_pins":pins,"prior_proof_sha256":prior,"environment":accepted["environment"],"cases":cases,"symbol_categories":local["symbol_categories"],"accepted_source_manifest_sha256":hash("/tmp/zopro-grouping-module/production-source-manifest.json"),"candidate_build_pins_sha256":hash(r.join("build-pins.json")),"candidate_rustflags":read(r.join("native-plan.json"))["steps"][2]["environment"]["RUSTFLAGS"],"candidate_native_core_tests":113,"accepted_target_core_tests_inherited":109,"accepted_target_field_tests_inherited":33,"adopted":false});save(c.join("manifest.json"),&manifest);
 let base="558215002830.dkr.ecr.eu-north-1.amazonaws.com/zolana-prover:bench-latest-c7a-profile-20261025";let o=Command::new("docker").args(["image","inspect",base,"--format","{{.Id}}"] ).output().unwrap();assert!(o.status.success());assert_eq!(String::from_utf8(o.stdout).unwrap().trim(),manifest["parent_image_id"].as_str().unwrap());fs::write(c.join("Dockerfile"),format!("FROM {base}\nCOPY lb-accepted lb-candidate lb-adapter lb-runner lb-xtask gnark-verify /usr/local/bin/\nCOPY zopro-keys.lock /manifest/zopro-keys.lock\nCOPY basis /lb-basis\nCOPY manifest.json /lb/manifest.json\nENTRYPOINT [\"/usr/local/bin/lb-runner\"]\n")).unwrap();let log=fs::File::create(r.join("docker-build.log")).unwrap();assert!(Command::new("docker").args(["build","--pull=false","-t","zopro-lower-bound-c7a:preflight"]).arg(&c).stdout(Stdio::from(log.try_clone().unwrap())).stderr(Stdio::from(log)).status().unwrap().success());save(r.join("image-prepared.json"),&json!({"status":"built; not published or launched","container_pins":pins.len(),"source_manifest":manifest,"parent_image_checked":true}));println!("Built all-nine exact preflight image; prior5340,no cloudresources");}
